        ['key' => 'vendors', 'title' => 'Vendors', 'description' => 'Upload the Zoho vendors export. Each vendor becomes an ERP vendor keyed by its Display Name.', 'supported' => true, 'executable' => true, 'datasets' => ['contacts'], 'destination' => 'account.vendors.index'],
        ['key' => 'payment_accounts', 'title' => 'Bank, cash and payment accounts', 'description' => 'Upload the Zoho Chart of Accounts export again. Its Bank, Cash and Credit Card accounts become ERP bank accounts linked to the chart accounts from step 2.', 'supported' => true, 'executable' => true, 'datasets' => ['chart_of_accounts'], 'destination' => 'account.bank-accounts.index'],
        ['key' => 'income_expense_categories', 'title' => 'Revenue and expense categories', 'description' => 'Upload the Zoho Chart of Accounts export again. Income accounts become revenue categories and Expense, Other Expense and Cost Of Goods Sold accounts become expense categories, each named and linked like its account.', 'supported' => true, 'executable' => true, 'datasets' => ['chart_of_accounts'], 'destination' => null],
        ['key' => 'quotations', 'title' => 'Quotations', 'description' => 'Upload the Zoho Estimates export. Each estimate becomes an ERP quotation with its lines, totals matching Zoho to the cent, and its Zoho status kept in the notes.', 'supported' => true, 'executable' => true, 'datasets' => ['quotations'], 'destination' => 'account.quotations.index'],
        ['key' => 'sales_invoices', 'title' => 'Sales invoices', 'description' => 'Upload the Zoho Invoices export. Live invoices import posted with their journal entry and stay unpaid until the Customer payments step; drafts import as drafts; void invoices are skipped. Totals match Zoho to the cent.', 'supported' => true, 'executable' => true, 'datasets' => ['sales_invoices'], 'destination' => 'sales-invoices.index'],
