        ['key' => 'credit_notes', 'title' => 'Credit notes', 'description' => 'Upload the Zoho Credit Notes export. Credits import approved with their journal entry (each line reduces its Zoho revenue account) and their full balance open; applying them to invoices is the Credit applications step. Totals match Zoho to the cent.', 'supported' => true, 'executable' => true, 'datasets' => ['credit_notes'], 'destination' => 'account.credit-notes.index'],
        ['key' => 'vendor_credits', 'title' => 'Vendor credits', 'description' => 'Upload the Zoho Vendor Credits export. Credits import approved with their journal entry (each line reduces its Zoho account) and their full balance open; applying them to bills is the Credit applications step. Totals match Zoho to the cent.', 'supported' => true, 'executable' => true, 'datasets' => ['vendor_credits'], 'destination' => 'account.debit-notes.index'],
        ['key' => 'customer_payments', 'title' => 'Customer payments and allocations', 'description' => 'Upload the Zoho Customer Payments export. Each payment is created cleared on its deposit account, applied to its invoices exactly as in Zoho (invoices become paid or partly paid) and posted with its journal entry. Totals match Zoho to the cent.', 'supported' => true, 'executable' => true, 'datasets' => ['customer_payments', 'customer_payment_allocations'], 'destination' => 'account.customer-payments.index'],
        ['key' => 'vendor_payments', 'title' => 'Vendor payments and allocations', 'description' => 'Upload the Zoho Vendor Payments export. Each payment is created cleared on its paid-through account, applied to its bills exactly as in Zoho and posted with its journal entry; an unapplied amount is kept as an advance to the vendor, as Zoho does. Totals match Zoho to the cent.', 'supported' => true, 'executable' => true, 'datasets' => ['vendor_payments', 'vendor_payment_allocations'], 'destination' => 'account.vendor-payments.index'],
        ['key' => 'credit_applications', 'title' => 'Credit applications and refunds', 'description' => 'Upload the Zoho Refund History report, and a credit split sheet (Credit Note Number, Invoice Number, Amount Credited, copied from the Credit Applied Invoices list of the credit note) for any credit note applied to several invoices whose split cannot be worked out. Credit notes and vendor credits are applied to the invoices and bills Zoho applied them to (from the files of the credit note and vendor credit steps) and refunds are posted from their bank account, so every credit ends as in Zoho.', 'supported' => true, 'executable' => true, 'multi_source' => true, 'datasets' => ['credit_refunds', 'credit_note_applications'], 'destination' => 'account.credit-notes.index'],
        ['key' => 'income_expenses', 'title' => 'Expenses', 'description' => 'Upload the Zoho Expenses export. Each expense is created posted with its journal entry (debit the Zoho expense account, credit the paid-through account) and bank register line; itemized expenses become one ERP expense per line. Expense categories are matched by Zoho account name, and created for expenses booked to non-expense accounts. Totals match Zoho to the cent. After the import, a newer full export can be uploaded: expenses already imported are checked and skipped, and only new ones are imported.', 'supported' => true, 'executable' => true, 'top_up' => true, 'datasets' => ['expenses'], 'destination' => 'account.expenses.index'],
        ['key' => 'bank_activity', 'title' => 'Bank transfers and petty cash', 'description' => 'Upload the Zoho Detailed General Ledger report (all accounts, all dates). Transfers between bank, cash, petty-cash and credit-card accounts become ERP bank transfers; transfers to or from other accounts (partner loans, staff accounts), owner contributions and expense refunds post as journals with their bank register line; other and interest income become revenues. Everything else in the report belongs to other steps and is skipped. Totals match Zoho to the cent.', 'supported' => true, 'executable' => true, 'datasets' => ['general_ledger'], 'destination' => 'account.bank-transfers.index'],
        ['key' => 'inventory_cutover', 'title' => 'Warehouse stock', 'description' => 'Zoho has no warehouse stock export. Copy and paste the approved SKU-by-warehouse opening quantities.', 'supported' => true, 'manual_entry' => true, 'datasets' => ['inventory_snapshot'], 'destination' => 'warehouses.index'],
        ['key' => 'accounting', 'title' => 'Manual journals', 'description' => 'Upload the Zoho Journals export. Each published journal is posted as an ERP manual journal with its Zoho number as the reference (cash-basis-only journals are skipped, as in the Zoho accrual ledger). Accounts Receivable and Payable lines post to the control accounts the invoices and bills use, bank lines add their bank register line, and bills Zoho paid by journal are marked paid. Totals match Zoho to the cent.', 'supported' => true, 'executable' => true, 'datasets' => ['manual_journals'], 'destination' => 'account.journal-entries.index'],
        ['key' => 'reconciliation', 'title' => 'Final reconciliation', 'description' => 'Upload the Zoho Trial Balance report, either "As of" a date or "From" the first transaction "To" a date, and optionally the AR and AP Aging Summary reports. Every account balance in ERP on that date is compared with Zoho: bank, cash, receivables, payables, equity, income and expenses. Each customer and vendor balance is compared with the aging reports. The migration is confirmed only when everything matches; nothing is changed.', 'supported' => true, 'executable' => true, 'multi_source' => true, 'datasets' => ['trial_balance', 'ar_aging', 'ap_aging'], 'destination' => 'account.reports.index'],
    ];

    public function all(): array
    {
        return array_map(fn (array $stage, int $index) => $stage + [
            'position' => $index + 1,
            'previous_key' => $index > 0 ? self::STAGES[$index - 1]['key'] : null,
            'upload_guide' => ZohoUploadGuide::for($stage['key']),
        ], self::STAGES, array_keys(self::STAGES));
    }

    public function find(string $key): ?array
    {
        foreach ($this->all() as $stage) {
            if ($stage['key'] === $key) {
                return $stage;
            }
        }

        return null;
    }
}
